begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values('11000000-0000-4000-8000-000000000001','metadata-editor@example.test'),('11000000-0000-4000-8000-000000000002','metadata-reviewer@example.test'),('11000000-0000-4000-8000-000000000003','metadata-outsider@example.test');
insert into academy.editor_members(user_id,role) values('11000000-0000-4000-8000-000000000001','editor'),('11000000-0000-4000-8000-000000000002','reviewer');
select ok(not has_table_privilege('anon','academy.metadata_snapshots','select'),'Primary metadata stays in private editorial boundary');
select ok(not has_table_privilege('authenticated','academy.metadata_snapshots','insert'),'Editors cannot forge fetched snapshots');
select ok(not has_table_privilege('authenticated','academy.identity_proposals','insert'),'No direct client proposals');
select ok(not has_table_privilege('authenticated','academy.identity_confirmations','insert'),'No direct client confirmations');
select ok(not has_table_privilege('authenticated','academy.pending_resolutions','insert'),'No direct client resolution history');
select ok(not has_table_privilege('authenticated','academy.event_reconciliations','insert'),'No direct client event links');
select ok(not has_function_privilege('authenticated','academy.claim_metadata(text)','execute'),'Only worker can acquire metadata provider lease');
select ok(not has_function_privilege('authenticated','academy.finish_metadata(text,uuid,integer,text,jsonb,integer)','execute'),'Only worker can persist fetched snapshots');
select ok(not has_function_privilege('anon','academy.resolve_pending(uuid,uuid,integer,text,uuid)','execute'),'Anon cannot resolve identity');
select ok(not has_table_privilege('service_role','academy.metadata_snapshots','update'),'Worker cannot overwrite snapshots');
select ok(not has_table_privilege('service_role','academy.pending_resolutions','delete'),'Worker cannot delete append-only history');
update academy.feed_locks set token=null,expires_at=null,next_allowed_at=now()-interval '1 second';
create temp table metadata_ctx(token uuid,snapshot uuid);
insert into metadata_ctx(token) select academy.claim_metadata('arxiv:9911.00001');
select ok((select token is not null from metadata_ctx),'Metadata worker claims shared lease');
select is(academy.claim_feed('arxiv-ai'),null::jsonb,'Feed cannot race with arXiv lookup');
select is(academy.claim_metadata('arxiv:9911.00002'),null::uuid,'Second arXiv lookup cannot bypass provider lock');
select throws_ok($$select academy.finish_metadata('arxiv:9911.00001',gen_random_uuid(),404,null,null)$$,'42501','Metadata lease lost','Wrong token cannot persist');
select lives_ok($$select academy.finish_metadata('arxiv:9911.00001',(select token from metadata_ctx),429,null,null,120)$$,'429 recorded without fabricated metadata');
select is((select count(*) from academy.metadata_snapshots where identity='arxiv:9911.00001'),0::bigint,'Rate limit is not metadata confirmation');
select ok((select next_allowed_at>=now()+interval '119 seconds' from academy.feed_locks where provider='arxiv'),'Retry-After applies to feeds and enrichment');
select is(academy.claim_feed('arxiv-physics'),null::jsonb,'Shared cooldown prevents retry storm');
select throws_ok($$select academy.claim_metadata('https://127.0.0.1/private')$$,'22023','Invalid publication identity','No arbitrary target');
update academy.feed_locks set next_allowed_at=now()-interval '1 second' where provider='arxiv';
update metadata_ctx set token=academy.claim_metadata('arxiv:9911.00001');
update metadata_ctx set snapshot=academy.finish_metadata('arxiv:9911.00001',token,200,'synthetic test payload','{"identity":"arxiv:9911.00001","provider":"arxiv","title":"Synthetic primary metadata","bibliographicStatus":"metadata_confirmed","scientificStatus":"unverified"}');
select ok((select snapshot is not null from metadata_ctx),'Worker persists immutable snapshot');
select is((select payload_hash from academy.metadata_snapshots where id=(select snapshot from metadata_ctx)),encode(extensions.digest(convert_to('synthetic test payload','UTF8'),'sha256'),'hex'),'Hash computed by DB from exact provider payload');
select throws_ok($$update academy.metadata_snapshots set raw_payload='changed' where id=(select snapshot from metadata_ctx)$$,'23000',null,'Snapshot cannot be changed even by admin command');
select throws_ok($$delete from academy.metadata_snapshots where id=(select snapshot from metadata_ctx)$$,'23000',null,'Snapshot cannot be deleted through ordinary commands');
set local role authenticated;
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000003',true);
select is((select count(*) from academy.metadata_snapshots where identity='arxiv:9911.00001'),0::bigint,'Nonmember cannot read primary snapshots');
select throws_ok($$select academy.request_metadata('arxiv:9911.00001')$$,'42501','Editor role required','Nonmember cannot enqueue');
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000002',true);
select is((select count(*) from academy.metadata_snapshots where identity='arxiv:9911.00001'),1::bigint,'Reviewer can read snapshots');
select throws_ok($$select academy.request_metadata('arxiv:9911.00001')$$,'42501','Editor role required','Reviewer cannot enqueue');
select throws_ok($$select academy.propose_identity(gen_random_uuid(),gen_random_uuid())$$,'42501','Editor role required','Reviewer cannot propose');
select throws_ok($$select academy.confirm_identity(gen_random_uuid(),'Review reason for denial',gen_random_uuid())$$,'42501','Editor role required','Reviewer cannot confirm relation');
select throws_ok($$select academy.resolve_pending(gen_random_uuid(),gen_random_uuid(),0,'Review reason for denial',gen_random_uuid())$$,'42501','Editor role required','Reviewer cannot resolve pending item');
select throws_ok($$select academy.reconcile_events(array[gen_random_uuid()],gen_random_uuid(),'initial_preprint','initialPublished','{}','Review reason for denial',gen_random_uuid())$$,'42501','Editor role required','Reviewer cannot reconcile events');
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000001',true);
select lives_ok($$select academy.request_metadata('arxiv:9911.00001')$$,'Editor can enqueue metadata');
select throws_ok($$select academy.propose_identity(gen_random_uuid(),gen_random_uuid())$$,'22023','Explicit primary relationship required','No arbitrary identity link proposal');
select throws_ok($$select academy.resolve_pending(gen_random_uuid(),gen_random_uuid(),0,'Sufficient explanation',gen_random_uuid())$$,'22023','Pending active item and metadata required','Cannot resolve nonexistent item');
select * from finish();
rollback;
